"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7580"],{81718(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.campos_obrigatorios","status":422,"titulo":"regra.versao, fator e baseLegal.id s\xe3o obrigat\xf3rios quando regra.codigo \xe9 informado"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.campos_obrigatorios","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["A declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso informou a regra do fator\\n(`regra.codigo`), mas faltou ao menos um dos tr\xeas campos que a acompanham: a vers\xe3o da regra\\n(`regra.versao`), o multiplicador da nota (`fator`) ou a base legal do fator\\n(`baseLegal.id`). Os tr\xeas s\xe3o obrigat\xf3rios sempre que a regra \xe9 informada, porque\\n\xe9 deles que o sistema monta o fator congelado do processo: a regra e a vers\xe3o dizem como o\\nacr\xe9scimo \xe9 calculado, o multiplicador diz quanto vale, e a base legal fixa os munic\xedpios\\na que ele se aplica.","A mensagem de detalhe da resposta lista os tr\xeas campos, sem dizer qual deles faltou; confira\\nos tr\xeas no corpo enviado. A recusa vem como uma viola\xe7\xe3o \xfanica, sem a lista `errors[]`, e\\nnada \xe9 gravado.","A confer\xeancia vem depois da que recusa a declara\xe7\xe3o de que o fator n\xe3o se aplica, mas traz\\ncampos do fator\\n([`fada_nao_aplica_com_configuracao`](/erros/uniplus.selecao.processo_seletivo.fada_nao_aplica_com_configuracao)),\\ne da que exige a regra quando o processo declara aplicar o fator\\n([`fada_aplica_sem_configuracao`](/erros/uniplus.selecao.processo_seletivo.fada_aplica_sem_configuracao)).\\nEla vem antes de qualquer consulta ao cat\xe1logo de regras\\n([`regra_nao_encontrada`](/erros/uniplus.selecao.configuracao_do_fada.regra_nao_encontrada)),\\nao cadastro de bases legais\\n([`base_legal_nao_encontrada`](/erros/uniplus.selecao.configuracao_do_fada.base_legal_nao_encontrada))\\ne \xe0 confer\xeancia dos valores do fator, do teto e do fato de elegibilidade. Antes de todas elas\\nsaem a recusa de acesso, a confer\xeancia do formato dos n\xfameros (o `fator` e o `teto` aceitam\\nat\xe9 quatro casas decimais) e a recusa de edi\xe7\xe3o de processo j\xe1 publicado fora de uma\\nretifica\xe7\xe3o ([`mutacao_pos_publicacao_bloqueada`](/erros/uniplus.selecao.processo_seletivo.mutacao_pos_publicacao_bloqueada))."],"comoResolver":["Envie a declara\xe7\xe3o com `aplica: true` e os quatro campos do fator juntos:","- `regra.codigo` e `regra.versao`: a regra e a vers\xe3o do cat\xe1logo de regras. Hoje o cat\xe1logo\\n  tem uma \xfanica regra do tipo regra do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA), `FADA_MULTIPLICATIVO`, na vers\xe3o `v1`;\\n- `fator`: o multiplicador aplicado \xe0 nota, maior que zero, com at\xe9 quatro casas decimais e no m\xe1ximo seis d\xedgitos no total, contados os zeros finais;\\n- `baseLegal.id`: o identificador da base legal do fator, do cadastro de bases\\n  legais do fator no m\xf3dulo Configura\xe7\xe3o.","O `teto` e o c\xf3digo do fato que decide quem recebe o acr\xe9scimo (`fatoElegibilidadeCodigo`)\\nseguem opcionais nesta confer\xeancia. Se o fator n\xe3o se aplica ao processo, declare\\n`aplica: false` e n\xe3o envie nenhum outro campo do fator."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);